int sensor = A0;  // Pin conectado al terminal central del potenciómetro
int valor;       // Almacena la conversión analógica

void setup() {
    Serial.begin(9600); // Inicia la comunicación serie
}

void loop() {
    valor = analogRead(sensor); // Lee voltaje variable (0 a 1023)

    Serial.print("Valor: ");    // Imprime la etiqueta en la consola
    Serial.println(valor);       // Imprime el valor numérico y salta de línea

    delay(500);                 // Pausa de medio segundo entre lecturas
}
